Consider a sequence of $X_1,X_1,\ldots$ on complete Riemannian manifold $M$. Furthermore let $I: F\to [0,\infty]$.
\begin{enumerate}
\item We say that $I$ is a good rate function if for every $c\geq 0$, the set $\{x~|~I(x)\leq c\}$ is compact.
    \item We say that the sequence $\{X_n\}_{n\geq 1}$ is \textit{exponentially tight} if for all $\alpha>0$ there exists a compact set $K_\alpha \subseteq F $ such that 
    \begin{equation*}
        \limsup_{n\to \infty}\frac{1}{n}\log X_n(K^c_\alpha)<-\alpha.
    \end{equation*}
    \item We say that the sequence $\{X_n\}_{n\geq 1}$ satisfies the \textit{large deviation principle} with rate $n$ and good rate function $I$, denoted by
    \begin{equation}
        \mathbb{P}[X_n \backsim a]\approx \mathrm{e}^{-nI(a)},
    \end{equation}
    \begin{enumerate}[(i)]
    \item if we have for every closed set $A\subseteq F$ the upper bound,
        \begin{equation*}
            \limsup_{n\to \infty} \frac{1}{n}\log\mathbb{P}[X_n\in A]\leq -\inf_{x \in F}I(x).
        \end{equation*}
            \item and for every open set $U\subseteq F$ the lower bound,
        \begin{equation*}
            \liminf_{n\to \infty}\frac{1}{n}\log \mathbb{P}[X_n\in U]\geq -\inf_{x\in U}I(x).
        \end{equation*}
        \end{enumerate}
        \end{enumerate}

Let $f\in C^{\infty}(M)$, and $\Tilde{f}=f\circ \mathbf{p}$ its lift to $O(M)$. Then for any $u\in O(M)$,
\begin{equation*}
	\Delta_Mf(x)=\Delta_{O(M)}\Tilde{f}(u),
\end{equation*}
where $x=\mathbf{p}u$.

By the It\^{o} formula, for any $f(\cdot)\in C^2_0(M)$,
	\begin{equation*}
		f(X_n(t))-f(x_0)-\int^t_0A_n^{M}f(X_n(s))\mathrm{d}s=\frac{1}{\sqrt{n}}\int^t_0\langle (u_n(s))^{-1
		}\mathrm{grad}f(X_n(s)),\mathrm{d}W(s)\rangle
	\end{equation*}
	is a martingale up to the life time $\zeta$; that is $X^\varepsilon_n(t)$ is the diffusion process generated by $A^M_n$, and we call it the $A^M_n$-diffusion process.

\label{lem_Mass_conservation}
		Let $\mathcal{L}$ be an elliptic diffusion operator with semigroup $\mathbf{P}=(P_t)_{t\geq 0}$, symmetric with respect to a positive measure $\mu$, on a smooth complete connected manifold $M$. If the $CD(\rho,\infty)$ curvature condition 
		\begin{equation*}
			\mathcal{R}(L)=\mathcal{R}_g-\nabla Z\geq \rho g
		\end{equation*}
		holds for some $\rho\in \mathbb{R}$, then for all $t\geq 0$, $P_t(\mathbbm{1})=\mathbbm{1}$.
		$\mathcal{R}_g$ is the Ricci tensor of the (co)-metric $g$.

\label{ass_b_linear_growth} Fix $x_0\in M$ and define $r(x)=d(x,x_0)$. We say that $b$ is linear growth if there exists a constant $C>0$ such that, for all $x\in M$,
\begin{equation*}
    |b(x,i)|\leq C(1+r(x)),~~~\forall~i\in S.
\end{equation*}

We say that $b$ is linear growth if there exists a constant $C>0$ such that, for all $x\in M$,
\begin{equation*}
    |b(x,i)|\leq C(1+r(x)),~~~\forall~i\in S.

\label{ass_b_one_side}
    We say that $b$ is locally one-sided Lipschitz function if for any compact sets $K\subseteq M$, there exists a constant $C_K> 0$ such that, for all $x$, $y\in K$, it holds that \begin{equation*}
    \mathrm{d}_x\left(\frac{1}{2}d^2(\cdot, y)\right)(x)b(x,i)-\mathrm{d}_y\left(-\frac{1}{2}d^2(x,\cdot)\right)(y)b(y,i)\leq C_Kd^2(x,y),~~~\forall i\in S,
    \end{equation*}
    where $d(x,y)<i(K)$ and $i(K)$ is the injectivity radius of $K$ defined in \Cref{se_Riemannian_manifold}.

We say that $b$ is locally one-sided Lipschitz function if for any compact sets $K\subseteq M$, there exists a constant $C_K> 0$ such that, for all $x$, $y\in K$, it holds that \begin{equation*}
    \mathrm{d}_x\left(\frac{1}{2}d^2(\cdot, y)\right)(x)b(x,i)-\mathrm{d}_y\left(-\frac{1}{2}d^2(x,\cdot)\right)(y)b(y,i)\leq C_Kd^2(x,y),~~~\forall i\in S,
    \end{equation*}
    where $d(x,y)<i(K)$ and $i(K)$ is the injectivity radius of $K$ defined in \Cref{se_Riemannian_manifold}.

\label{asm_conti_manifold}
	For any compact sets $K\subseteq M$, there exists a constant $C_K>0$ such that 
	\begin{equation*}
		|q_{ij}(x)-q_{ij}(y)|\leq C_Kd(x,y),~~x,~y\in K,~i,~j \in S.
	\end{equation*}

\label{ass_bfH_bounded}
    Let $M$ be a Riemannian manifold, there exists a operator $\mathbf{H}\subseteq C_b^1(M)\times C_b(M)$ with domain
    \begin{equation*}
        \mathcal{D}(\mathbf{H})=\{f\in C^1_b(M)~| ~ c_f = \sup_{z} \left\{ -\mathbf{H}f(z) \right\} < \infty \}.
    \end{equation*}

\label{thm_LDPmanifold} 
Let $(X_n(t),\Lambda_n(t))$ be the Markov processes on $M\times S$. Consider the setting of Assumptions \ref{assu_varn_manifold}, \ref{ass_b_linear_growth}, \ref{ass_b_one_side}, \ref{asm_conservative_manifold}, \ref{asm_conti_manifold} and \ref{ass_bfH_bounded}.
	Suppose that 
	the large deviation principle holds for $X_n(0)$ on $M$ with speed $n$ and a good rate function $I_0$.
\par
Then, the large
deviation principle is satisfied with speed $n$ for the processes $X_n(t)$ with a good rate function $I$ having action-integral representation,
\begin{equation*}
	I(\gamma)=
	\begin{cases}
		I_0(\gamma(0))+\int^\infty_0\mathcal{L}\left(\gamma(s),\dot{\gamma}(s)\right)\mathrm{d}s,&\mbox{if~$\gamma\in\mathcal{AC}(M)$,}\\
		\infty,&\mbox{otherwise.}
	\end{cases}
\end{equation*}
where $\mathcal{L}: TM \to  [0, \infty]$ is the Lagrangian transform of $\mathcal{H}$ given by $\mathcal{L}(x, v) = \sup_{p\in T^*_xM} \{\langle v, p\rangle - \mathcal{H}(x, p)\} $,
and \begin{equation*}
\begin{split}
\mathcal{H}(x,\mathrm{d}f(x))=\sup_{\pi\in\mathcal{P}(S)}\big\{\int_M B_{x,\mathrm{d}f(x)}(z)\pi(\text{d}z)-\mathcal{I}(x,\pi)\big\}
\end{split}
\end{equation*}
is given in \eqref{eqn_bfHH}.

Recall that $\mathcal{L}: TM \to  [0, \infty]$, defined as 
\begin{equation*}
	\mathcal{L}(x, v) = \sup_{p\in T^*_xM}\{\langle p, v\rangle-\mathcal{H}(x,~p)\}.   
\end{equation*}

\label{proposition_bridge}
		Let $(X_n(t),\Lambda_n(t))$ be Markov processes on $M\times S$.
		Suppose that
		\begin{enumerate}
			\item  \label{item_a} $X_n(0)$  satisfies large deviation principle;
			\item \label{item_b} there exists an operator $H$ such that we have $\|H_n-H\|\to 0$ as $n\to\infty$;
			\item \label{item_c} we have exponential tightness of the process $(X_n(t),\Lambda_n(t))$;
			\item  \label{item_d} for all $\lambda>0$ and $h\in C_b(M)$, the comparison principle holds for $f-\lambda Hf=h$ with same $H$ as in \cref{item_b}, and there exists a unique solution $R(\lambda)h$;
  \item \label{item_e} $R(\lambda)h=\mathbf{R}(\lambda)h$.
		\end{enumerate}

		Then the following hold:
		\begin{enumerate}[(i)]
			\item \label{item_Limit of nonlinear semigroup} (Limit of nonlinear semigroup) For each $x\in M$, $f\in \overline{\mathcal{D}(H)}$, $f_n\in \mathcal{B}(M\times S)$ and $t\geq 0$, if $\|f_n-f\|\to 0$ as $n\to \infty$, there exists  a unique semigroup $V(t)$ such that  
\begin{equation}\label{nonlinear}
		\lim_{n\to\infty}\|V_n(t)f_n-V(t)f\|=0
			\end{equation}
		and 
  \begin{equation}\label{eqn_RV}
  \lim_{m\to\infty}\|R(t/m)^m f-V(t)f\|=0.
  \end{equation}
			\item \label{item_Large deviation principle}(Large deviation principle) $X_n(t)$ satisfies the large deviation principle with good rate function $I$ given by
			\begin{equation}\label{eqn_rate_function_1}
			I(x)=I_0(x(t_0))+\sup_{k\in \mathbb{N}}\sup_{0=t_0<t_1<\cdots<t_k<\infty}\sum_{i=0}^{k}I^V_{t_{i+1}-t_{i}}(x(t_{i+1})|x(t_{i})),
			\end{equation}
			where for $\Delta t=t_{i+1}-t_{i}>0$ and $x(t_{i+1}),x(t_{i})\in M$, the conditional rate functions $I^V_{\Delta t}(x(t_{i+1})~ |~ x(t_{i}))$ are 
			\begin{equation*}
				I^V_{\Delta t}(x(t_{i+1})~|~x(t_{i}))=\sup_{f\in C_b(M)}[f(x(t_{i+1}))-V(\Delta t)f(x(t_{i}))].
			\end{equation*} 
			\item \label{item_Action-integral representation of the rate function} (Action-integral representation of the rate function) 
  The rate function $I$ of \eqref{eqn_rate_function_1} together with $V(t)=\mathbf{V}(t)$ is also  given in Action-integral representation,
\begin{equation}\label{eqn_AC}
I(\gamma)=
\begin{cases}
I_0(\gamma(0))+\int^\infty_0\mathcal{L}(\gamma(s),\dot{\gamma}(s) )\text{d}s,&\mbox{if~$\gamma\in \mathcal{AC}(M)$,}\\
					\infty,&\mbox{otherwise.}
				\end{cases}
			\end{equation}
		\end{enumerate}

\label{pro_convergence_of_operator}
	 Let $(X_n(t),\Lambda_n(t))$ be a Markov process on $M\times S$ with generator $A^M_n$ in \eqref{eqn_ANM}. For $H_n$ in \eqref{eqn_HVN}, then there exists a multivalued limit operator $H$ such that $\|H_n-H\|\to0$ as $n\to \infty$ and $H$ is given by
		\begin{equation}\label{eqn_multivale_H}
		H:=\Big\{(f,H_{f,\phi})\Big|f\in C_b(M), H_{f,\phi}\in C_b(M\times S)~\mbox{and}~\phi\in C^2(M\times S)\Big\},
	\end{equation}
 where 
 \begin{equation}\label{eqn_HFPHi}
     H_{f,\phi}(x,i)=b(x,i)\mathrm{d} f(x)+\frac{1}{2}|\mathrm{d}f(x)|^2+\sum_{j\in S}q_{ij}(x)[e^{\phi(x,j)-\phi(x,i)}-1].
 \end{equation}

\begin{equation}\label{eqn_multivale_H}
		H:=\Big\{(f,H_{f,\phi})\Big|f\in C_b(M), H_{f,\phi}\in C_b(M\times S)~\mbox{and}~\phi\in C^2(M\times S)\Big\},
	\end{equation}

By the generator $A^M_n$ in \eqref{eqn_ANM}, for $\mathrm{e}^{nf}\in \mathcal{D}(A^M_n)$ we get a nonlinear generator
\begin{equation}\label{eqn_HnF}
\begin{split}
   H_nf(x,i)&=\frac{1}{n}e^{-nf}A_n^Me^{nf}(x,i)\\
    &= b(x,i)\mathrm{d} f(x,i)+\frac{1}{2}|\mathrm{d}  f(x,i)|^2+\frac{1}{2n}\Delta_Mf(x,i)\\
    &\quad+\sum_{j\in S}q_{ij}(x)[e^{n(f(x,j)-f(x,i))}-1].
\end{split}
\end{equation}
However, when $n\to \infty$, \eqref{eqn_HnF} is not convergent due to the divergence of the third term. To proceed, instead of using $f$ in \eqref{eqn_HnF}, we take a sequence 
\begin{equation*}
    f_n(x,i)=f(x)+\frac{1}{n}\phi(x,i),~~~\forall~f\in C^\infty(M)~\mbox{and}~\phi\in C^2(M\times S).
\end{equation*}
Obviously, $\mathrm{d}f_n(x,i)=\mathrm{d}f(x)+\frac{1}{n}\mathrm{d}\phi(x,i)$. This, together with \eqref{eqn_HnF}, we have
\begin{align*}
    H_nf_n(x,i)
    &=b(x,i) \left(\mathrm{d}f(x)+\frac{1}{n}\mathrm{d}\phi(x,i)\right)+\frac{1}{2} \left|\mathrm{d}f(x)+\frac{1}{n}\mathrm{d}\phi(x,i)\right|^2\\
    &\quad+\frac{1}{2n}\Delta_M\left(f(x)+\frac{1}{n}\phi(x,i)\right)+\sum_{j\in S}q_{ij}(x)[e^{\phi(x,j)-\phi(x,i)}-1].
\end{align*}
Let $n\to \infty$ in above equality, under uniform topology we obtain the limit
\begin{equation*}
\begin{split}
    &H_{f,\phi}(x,i)\\
    &=b(x,i) \mathrm{d} f(x)+\frac{1}{2}
    \left|\mathrm{d}  f(x)\right|^2+\sum_{j\in S}q_{ij}(x)[e^{\phi(x,j)-\phi(x,i)}-1]\\
&=:H_l(x,i)+H_q(x)+\mathrm{e}^{-\phi(x,i)}R_x\mathrm{e}^{\phi(x,i)}, 
\end{split}
\end{equation*}
where the linear part is
\begin{equation*}
    H_l(x,i)=b(x,i)\text{d} f(x),
\end{equation*}
the nonlinear part is
\begin{equation}\label{eqn_Hq}
   H_q(x)=\frac{1}{2}
   \left|\mathrm{d}  f(x)\right|^2,
\end{equation}
and the switching part is
\begin{equation*}
  R_x \mathrm{e}^{\phi(x,i)}=\sum_{j\in S}q_{ij}(x)[e^{\phi(x,i)}-e^{\phi(x,j)}].
\end{equation*}
The proof is completed.

\label{lem_eigen} Let Assumptions \ref{asm_conservative_manifold} and \cref{asm_conti_manifold} be satisfied. 
	For each $(x,\mathrm{d}f(x))$, there exist $\bar{\phi}>0$ and a unique eigenvalue $\tau(x,\mathrm{d}f(x))\in \mathbb{R}$ such that
\begin{equation}\label{eigenvalue}
	Q_{x,p}\bar{\phi}(i)=\tau(x,\mathrm{d}f(x))\bar{\phi}(i),
\end{equation}
with the operator $Q_{x,p}=B_{x,p}+R_x$. In detail, $\tau(x,\mathrm{d}f(x))$ is given by
\begin{equation}\label{eqn_eigenvalue}
\begin{split}
	\tau(x,\mathrm{d}f(x))&=\inf_{\pi\in \mathcal{P}(S)}\sup_{g>0}\int_M\frac{-Q_{x,p}g(z)}{g(z)}\pi(\text{d}z)\\
	&=-\sup_{\pi\in\mathcal{P}(S)}\inf_{g>0}\int_M\frac{Q_{x,p}g(z)}{g(z)}\pi(\text{d}z).
\end{split}
\end{equation}
Moreover, since 
\begin{equation}\label{eqn:eigenvalue}
	\tau(x,\mathrm{d}f(x))=-\mathcal{H}(x,\mathrm{d}f(x)),
\end{equation}
as a by-product, combining \eqref{eqn_eigenvalue} and \eqref{eqn:eigenvalue}, one has a single valued Hamiltonian 
\begin{equation}\label{eqn_Hxp}
\begin{split}
	\mathbf{H}(x):=\mathcal{H}(x,\mathrm{d}f(x))&=\sup_{\pi\in\mathcal{P}(S)}\inf_{g>0}\int_M\frac{Q_{x,\mathrm{d}f(x)}g(z)}{g(z)}\pi(\text{d}z)\\
	&=\sup_{\pi\in\mathcal{P}(S)}\big\{\int_M B_{x,\mathrm{d}f(x)}(z)\pi(\text{d}z)-\mathcal{I}(x,\pi)\big\},
\end{split}
\end{equation}
where
\begin{equation}\label{eqn_I(x,pi)}
	\mathcal{I}(x,\pi)=-\inf_{g>0}\int_M\frac{R_xg(z)}{g(z)}\pi(\text{d}z).
\end{equation}

\label{lem_fr}
    Let $M$ be a complete Riemannian manifold of dimension $d$. Fix $x_0\in M$ and define $r(x)=d(x,x_0)$. Under \Cref{ass_b_linear_growth}, there 
    exists an nonnegative smooth function $f\in C^\infty(M)$ satisfying   
\begin{equation}\label{eqn_fand_r}
        |f-r|\leq 1
    \end{equation}
    and
\begin{equation}\label{eqn_uniform_bound}
        |\mathrm{d}f|\leq 2
    \end{equation}
    such that 
\begin{equation}\label{eqn_Upsilon}
\Upsilon(x)=\frac{1}{2}\log(1+f^2(x)) 
\end{equation}
is a good containment function.

    Clearly $\Upsilon\geq 0$ and $\Upsilon(x_0)=0$, and $\Upsilon\in C^\infty(M)$.

    Now fix $c\geq 0$. By the continuity of $\Upsilon$, the set $\{x\in M~|~\Upsilon(x)\leq c\}$ is closed. By definition the set is bounded, and as $M$ is a complete finite dimensional Riemannian manifold, also compact.

    Note that for all $x\in M$,
    \begin{equation}\label{eqn_dUps}
\text{d}\Upsilon(x)=\frac{f(x)}{1+f^2(x)}\mathrm{d}f(x).
    \end{equation}

   This, together with  \Cref{ass_b_linear_growth}, \eqref{eqn_uniform_bound} and \eqref{eqn_fand_r}, for $z\in S$, we first estimate that
\begin{equation}\label{eqn_useoneside}
 \begin{split}
   b(x,z)  \mathrm{d}\Upsilon(x)&=b(x,z) \mathrm{d}f(x)\frac{f(x)}{1+f^2(x)} \\
    &\leq |b(x,z)| \cdot |\mathrm{d}f(x)|\cdot\frac{f(x)}{1+f^2(x)} \\&\leq 2C_b(1+r(x))\frac{f(x)}{1+f^2(x)} \\
    &\leq 2C_b(2+f(x))\frac{f(x)}{1+f^2(x)}.
 \end{split}
 \end{equation}
 Hence, $\sup_{x,z}b(x,z)\mathrm{d} \Upsilon(x)<\infty$.
    Now recall the Hamiltonian $\mathcal{H}$ in \eqref{eqn_Hxp}, from \eqref{eqn_useoneside}, we obtain
\begin{align*}
    \mathcal{H}(x,\mathrm{d}\Upsilon(x))&=\sup_{\pi\in\mathcal{P}(S)}\big\{\int_M B_{x,\mathrm{d}\Upsilon(x)}(z)\pi(\text{d}z)-\mathcal{I}(x,\pi)\big\}\\
    &\leq \int_M B_{x,\mathrm{d}\Upsilon(x)}(z)\pi(\text{d}z)\\
     &=\int_M \left( b(x,z)\mathrm{d}\Upsilon(x)+\frac{1}{2}| \mathrm{d}\Upsilon(x)|^2\right)\pi(\mathrm{d}z)\\
     &\leq C\int_M \left(\frac{f(x)}{1+f^2(x)}+\frac{f^2(x)}{1+f^2(x)}+\frac{f^2(x)}{(1+f^2(x))^2}\right)\pi(\mathrm{d}z),
\end{align*}
where the first inequality uses the definition of supremum and $\mathcal{I}(x,\pi)$ is nonnegative.
We conclude that $\sup_x \mathcal{H}(x,\mathrm{d}\Upsilon(x))<\infty$, which implies that $\Upsilon$ is a good containment function.

\label{pro_expo}
 Let $(X_n(t),\Lambda_n(t))$ be a Markov process corresponding to $A^M_n$, and $\Upsilon(x)$ be a good containment function in \eqref{eqn_Upsilon}. 
    Suppose that the sequence $(X_n(t),\Lambda_n(t))$ is exponentially tight with speed $n$.
    Then the sequence $(X_n(t),\Lambda_n(t))$ satisfies the exponential compact containment condition with speed $n$: for every $T > 0$ and $a \geq  0$, there exists a compact set $K_{a,T}\subseteq M$ such that
    \begin{equation*}
        \limsup_{n\to \infty} \frac{1}{n}\log \mathbb{P}[(X_n(t),\Lambda_n(t))\notin K_{a,T}\times S ~\mbox{for~some}~t\leq T]\leq -a.
    \end{equation*}

\label{lem_dddd}
    Let $x$, $y\in M$ and assume that $x\notin \mbox{cut}(y)$ (or equivalently, $y\notin \mbox{cut}(x)$), where $\mbox{cut}(\cdot)$ is a cut-locus. Then for all $V\in T_yM$ we have
    \begin{equation*}
		\mathrm{d}_y(d^2(x,\cdot))(y)(V)=2\langle \dot{\gamma}(1),~V
\rangle_{g(y)},    
\end{equation*}
where $\gamma: [0,1]\to M$ is the unique geodesic of minimal length connecting $x$ and $y$. Consequently, we obtain
\begin{equation}\label{eqn_tauxy}
   \tau_{x,y} \mathrm{d}_x(d^2(\cdot,y))(x)=-\mathrm{d}_y(d^2(x,\cdot))(y).
\end{equation}

    As $K$ is compact, the continuity of the injectivity radius $i$ implies there exists $R > 0 $ such that $i(K ) > R$. Pick $\Delta  =\frac{1}{3}R$ and let $\Phi: \mathbb{R}\to \mathbb{R}$ be a smooth increasing function such that 
    \begin{equation*}
\Phi(r)=
\begin{cases}
r ,&if ~\mbox{$|r|<\Delta$,}\\
1,&if~\mbox{$|r|>2\Delta$.}
\end{cases}
\end{equation*} Then the function $\Psi(x,y)=\frac{1}{2}\Phi(d^2(x,y))=\frac{1}{2}d^2(x,y)$, when $d(x,y)\leq \Delta$ and $x$, $y\in K$, is as desired.

\label{lem_pro3.7}
Let $u$ be bounded and upper semicontinuous, let $v$ be bounded and lower semicontinuous, let $\Psi:M^2\to \mathbb{R}^+$ be good penalization functions in \Cref{lem_smooth_function} and let $\Upsilon$ be a good containment function in \eqref{eqn_Upsilon}. 
\par
Fix $\delta>0$. For every $m>0$ there exist points $x_{\delta,m}$, $y_{\delta,m}\in M$, such that
\begin{equation}\label{eqn:Text_function}
\begin{split}
&\frac{u(x_{\delta,m})}{1-\delta}-\frac{v(y_{\delta,m})}{1+\delta}-m\Psi(x_{\delta,m},y_{\delta,m})-\frac{\delta}{1-\delta}\Upsilon(x_{\delta,m})-\frac{\delta}{1+\delta}\Upsilon(y_{\delta,m})\\
&=\sup_{x,y\in M}\big\{\frac{u(x)}{1-\delta}-\frac{v(y)}{1+\delta}-m\Psi(x,y)-\frac{\delta}{1-\delta}\Upsilon(x)-\frac{\delta}{1+\delta}\Upsilon(y)\big\}.
\end{split}
\end{equation}
Additionally, for every $\delta>0$ we have that
\begin{enumerate}
\item \label{item_iaa} The set $\{x_{\delta,m},~y_{\delta,m} ~|~m >0\}$ is relatively compact in $M$.
\item \label{item_ibb} All limit points of $\{(x_{\delta,m},~y_{\delta,m})\}_{m >0}$ are of the form $(z,~z)$ and for these limit points we have 
\begin{equation*}
 u(z)-v(z)=\sup_{x\in M}u(x)-v(x).   
\end{equation*}
\item \label{item_icc} We have
\begin{equation*}
\lim_{m\to\infty}m\Psi(x_{\delta,m},~y_{\delta,m})=0.
\end{equation*}
\end{enumerate}

(Multivalued operators)
\begin{itemize}
\item For $f\in C^{\infty}_l(M)$, $\delta\in(0,1)$ and $\phi\in C^2(M\times S)$. Set
\begin{equation*}
f^{\delta}_1(x):=(1-\delta)f(x)+\delta \Upsilon(x),
\end{equation*}
\begin{equation*}
H^\delta_{1,f,\phi}(x,i):=(1-\delta)H_{f,\phi}(x,i)+\delta C_{\Upsilon},
\end{equation*}
and set
\begin{equation*}
H_1:=\Big\{\left(f^{\delta}_1,H^\delta_{1,f,\phi}\right)\Big | f\in C^{\infty}_l(M),\delta\in(0,1),~\phi\in C^2(M\times S)\Big\}.
\end{equation*}
\item For $f\in C^{\infty}_u(M)$, $\delta\in(0,1)$ and $\phi\in C^2(M\times S)$. Set
\begin{equation*}
f^{\delta}_2(x):=(1+\delta)f(x)-\delta \Upsilon(x),
\end{equation*}
\begin{equation*}
H^\delta_{2,f,\phi}(x,i):=(1+\delta)H_{f,\phi}(x,i)-\delta C_\Upsilon,
\end{equation*}
and set
\begin{equation*}
H_2:=\left\{\left(f^{\delta}_2,H^\delta_{2,f,\phi}\right)\Big | f\in C^{\infty}_u(M),~\delta\in(0,1),~\phi\in C^2(M\times S)\right\}.
\end{equation*}
Noting that $H_{f,\phi}$ in $H_{1,f,\phi}^\delta$ and $H_{2,f,\phi}^\delta$ is obtained in \eqref{eqn_HFPHi}.
\end{itemize}

(Single valued operators)
\begin{itemize}
\item For $f\in C^{\infty}_l(M)$ and $\delta \in(0,1)$ set
\begin{equation*}
f^{\delta}_{\dagger}(x):=(1-\delta)f(x)+\delta \Upsilon(x),
\end{equation*}
\begin{equation*}
H^{\delta}_{\dagger,f}(x):=(1-\delta)\mathbf{H}f(x)+\delta C_{\Upsilon},
\end{equation*}
and set
\begin{equation*}
H_{\dagger}:=\left\{\left(f^{\delta}_\dagger,H^{\delta}_{\dagger,f}\right)\Big |f\in C^\infty_l(M),~\delta\in(0,1)\right\}.
\end{equation*}
\item For $f\in C^{\infty}_u(M)$ and $\delta\in(0,1)$ set
\begin{equation*}
f^{\delta}_{\ddagger}(x):=(1+\delta)f(x)-\delta \Upsilon(x),
\end{equation*}
\begin{equation*}
H^{\delta}_{\ddagger,f}(x):=(1+\delta)\mathbf{H}f(x)-\delta C_{\Upsilon},
\end{equation*}
and set
\begin{equation*}
H_{\ddagger}:=\Big\{\left(f^\delta_\ddagger,~H^\delta_{\ddagger,f}\right)\Big |f\in C^\infty_u(M),~\delta\in(0,1)\Big\}.
\end{equation*}
\end{itemize}
Noting that $\mathbf{H}$ in $H_{\dagger,f}^\delta$ and $H_{\ddagger,f}^\delta$ is obtained in \eqref{eqn_Hxp}.

\label{pro_compa_prin}
Let Assumptions \ref{ass_b_linear_growth}, \ref{ass_b_one_side}, \ref{asm_conservative_manifold} and \ref{asm_conti_manifold} be satisfied. Let $h_1$, $h_2\in C_b(M)$ and $\lambda>0$. Let $u$ be any subsolution to $f-\lambda H f=h_1$ and let $v$ be any supersolution to $f-\lambda Hf=h_2$. Then we have that
	\begin{equation*}
		\sup_{x\in M}u(x)-v(x)\leq\sup_{x}h_1(x)-h_2(x).
	\end{equation*}

\label{lem_1d}
Fix $\lambda>0$ and $h\in C_b(M)$.
\begin{enumerate}
\item Every subsolution to $f-\lambda H_1f=h$ is also a subsolution to $f-\lambda H_{\dagger}f=h$.
\item Every supersolution to $f-\lambda H_1f=h$ is also a supersolution to $f-\lambda H_{\ddagger}f=h$.
\end{enumerate}

\label{lem_bfd}
Fix $\lambda>0$ and $h\in C_b(M)$. 
\begin{enumerate}
\item Every subsolution to $f-\lambda \mathbf{H}f=h$ is also a subsolution to $f-\lambda H_\dagger f=h$.
\item Every supersolution to $f-\lambda \mathbf{H}f=h$ is also a supersolution to $f-\lambda H_{\ddagger} f=h$.	
\end{enumerate}

\label{lem_h1}
Fix $\lambda >0$ and $h\in C_b(M)$.
\begin{enumerate}
\item Every subsolution to $f-\lambda Hf=h$ is also a subsolution to $f-\lambda H_1f=h$.
\item  Every supersolution to $f-\lambda Hf=h$ is also a supersolution to $f-\lambda H_2f=h$.
\end{enumerate}

\label{Hd}
Assumptions \ref{assu_varn_manifold}, \ref{ass_b_one_side}, \ref{asm_conservative_manifold} and \ref{asm_conti_manifold} hold. Let $h_1$, $h_2\in C_b(M)$ and $\lambda>0$. Let $u$ be any subsolution to $f-\lambda H_{\dagger}f=h_1$ and let $v$ be any supersolution to $f-\lambda H_{\ddagger}f=h_2$. Then we have
\begin{equation}\label{eqn:results_comparison_principle}
\sup_{x\in M}u(x)-v(x)\leq\sup_{x\in M}h_1(x)-h_2(x).
\end{equation}


    For a sub and supersolution $u$ and $v$, $\delta \in (0,1)$ and $m \geq 1$, we follow \eqref{eqn:Text_function} and set
 \begin{equation}\label{eqn:Pdelta_m}
\Phi_{\delta,m}(x,y):=\frac{u(x)}{1-\delta}-\frac{v(y)}{1+\delta}-m\Psi(x,y)-\frac{\delta}{1-\delta}\Upsilon(x)-\frac{\delta}{1+\delta}\Upsilon(y),
\end{equation}
where $\Psi(\cdot,\cdot)$ is a smooth function we have given in \Cref{lem_smooth_function}. Since $\Upsilon$ has compact level sets, there exists $(x_{\delta,m},y_{\delta,m})\in M\times M$ satisfying 
\begin{equation}\label{eqn_Phi_sup}
\Phi_{\delta,m}(x_{\delta,m},~y_{\delta,m})=\sup_{(x,y)\in M\times M}\Phi_{\delta,m}(x,~y).
\end{equation}
In view of \eqref{eqn_Phi_sup}, it follows that $x_{\delta,m}$ is the unique maximizing point for
\begin{align*}
\sup_{x\in M}u(x)-\varphi_1^{\delta,m}(x)=u(x_{\delta,m})-\varphi_1^{\delta,m}(x_{\delta,m})
\end{align*}
where $\varphi_1^{\delta,m}$ is constructed by taking the appropriate remaining terms of \eqref{eqn:Pdelta_m}, with an additional penalization $(1-\delta)d^2(x,x_{\delta,m})$ to turn $x_{\delta,m}$ into the unique optimizer:
\begin{align*}
\varphi_1^{\delta,m}(x):&=-(1-\delta)\Phi_{\delta,m}(x,y_{\delta,m})+u(x)+(1-\delta)d^2(x,x_{\delta,m})\\
&=(1-\delta)\left(-\frac{u(x)}{1-\delta}+\frac{v(y_{\delta,m})}{1+\delta}+m\Psi(x,y_{\delta,m})+\frac{\delta}{1-\delta}\Upsilon(x)+\frac{\delta}{1+\delta}\Upsilon(y_{\delta,m})\right)\\
&\quad+u(x)+(1-\delta)d^2(x,x_{\delta,m})\\
&=(1-\delta)\left(\frac{v(y_{\delta,m})}{1+\delta}+m\Psi(x,y_{\delta,m})+\frac{\delta}{1-\delta}\Upsilon(x)+\frac{\delta}{1+\delta}\Upsilon(y_{\delta,m})\right)\\
&\quad+(1-\delta)d^2(x,x_{\delta,m})\\
&=(1-\delta)\bigg(m\Psi(x,y_{\delta,m})+d^2(x,x_{\delta,m})+\frac{\delta}{1+\delta}\Upsilon(y_{\delta,m})+\frac{v(y_{\delta,m})}{1+\delta}\bigg)+\delta\Upsilon(x).
\end{align*}
Since $u$ is a viscosity subsolution of $f-\lambda H_{\dagger}f=h_1$ we conclude that
\begin{equation}\label{eqn_sub_inequality}
u(x_{\delta,m})-\lambda\left[(1-\delta)\mathcal{H}(x_{\delta,m},p^1_{\delta,m})+\delta C_{\Upsilon}\right]\leq h_1(x_{\delta,m}),
\end{equation}
where
\begin{equation}\label{eqn_P1} p^1_{\delta,m}:=md_x\Psi(\cdot,y_{\delta,m})(x_{\delta,m})=m~ \mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m}).
\end{equation}
Similarly, we obtain that that $y_{\delta,m}$ it the unique optimizer for
\begin{equation*}
\inf_{y\in M}v(x)-\varphi_2^{\delta,m}(y)=v(y_{\delta,m})-\varphi_2^{\delta,m}(y_{\delta,m}),
\end{equation*}
where
\begin{align*}
\varphi^{\delta,m}_2(y):&=(1+\delta)\left(-m\Psi(x_{\delta,m},y)-d^2(y,y_{\delta,m})-\frac{\delta}{1-\delta}\Upsilon(x_{\delta,m})+\frac{u(x_{\delta,m})}{1-\delta}\right)-\delta\Upsilon(y).
\end{align*}
As $v$ is a viscosity supersolution of $f-\lambda H_{\ddagger}f=h_2$, we know then that
\begin{equation}\label{eqn_super_inequality}
v(x_{\delta,m})-\lambda\left[(1+\delta)\mathcal{H}(y_{\delta,m},p^2 _{\delta,m})-\delta C_{\Upsilon}\right]\geq h_2(y_{\delta,m}),
\end{equation}
where
\begin{equation}\label{eqn_P2}
p^2_{\delta,m}:=-m~\mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m}).
\end{equation}
By \cref{item_icc} of \Cref{lem_pro3.7}, we have
\begin{equation}\label{eq_md}
\lim_{m\to\infty}m\Psi(x_{\delta,m},y_{\delta,m})=0.
\end{equation}
Taking \eqref{eqn_sub_inequality}, \eqref{eqn_super_inequality} and \eqref{eq_md} into account, we obtain that
\begin{align}
\sup_{x\in M}u(x)-v(x)&\leq \liminf_{\delta\to0}\liminf_{m\to\infty}\left(\frac{u(x_{\delta,m})}{1-\delta}-\frac{v(y_{\delta,m})}{1+\delta}\right)\notag\\
&\leq \liminf_{\delta\to0}\liminf_{m\to\infty}\big\{\frac{h_1(x_{\delta,m})}{1-\delta}-\frac{h_2(y_{\delta,m})}{1+\delta}\label{eqn_k1}\\
&\quad+\frac{\delta}{1-\delta}C_{\Upsilon}+\frac{\delta}{1+\delta}C_{\Upsilon}\label{eqn_k2}\\
&\quad+ \lambda\big(\mathcal{H}(x_{\delta,m},p^1_{\delta,m})-\mathcal{H}(y_{\delta,m},p^2_{\delta,m})\big)\big\},
\end{align}
where in the first inequality we use \eqref{eqn_Phi_sup} and  drop the nonnegative functions  $d^2(\cdot,\cdot)$ and $\Upsilon(\cdot)$.
\par
The term \eqref{eqn_k2} vanishes as $\delta \to 0$.
For the term \eqref{eqn_k1}, the sequence $(x_{\delta,m},y_{\delta,m})$ takes its values in a compact set and, hence, admits converging subsequences as $m\to \infty$. 
By (b) of \Cref{lem_pro3.7}, these subsequences converge to points of the form $(x,x)$. 
Hence, by the above analysis, we get 
\begin{align*}
	\sup_{x\in M}u(x)-v(x)&\leq \lambda\liminf_{\delta\to0}\liminf_{m\to\infty} \big(\mathcal{H}(x_{\delta,m},p^1_{\delta,m})-\mathcal{H}(y_{\delta,m},p^2_{\delta,m})\big)\\
	&\quad+\sup_{x\in M}h_1(x)-h_2(x).
\end{align*}
It follows that the comparison principle holds for $f-\lambda H_\dagger f=h_1$ and $f-\lambda H_\ddagger f=h_2$ whenever for any $\delta>0$
\begin{equation}\label{eqn_H-H}
 	\liminf_{m\to\infty} \big(\mathcal{H}(x_{\delta,m},p^1_{\delta,m})-\mathcal{H}(y_{\delta,m},p^2_{\delta,m})\big)\leq0.
\end{equation}
\par
To that end, recall $\mathcal{H}(x,\mathrm{d}f(x))$ in \eqref{eqn_Hxp}:
\begin{equation*}
\mathcal{H}(x,\mathrm{d}f(x))=\sup_{\pi\in\mathcal{P}(S)}\big\{\int_M B_{x,\mathrm{d} f(x)}(z)\pi(\text{d}z)-\mathcal{I}(x,\pi)\big\},
\end{equation*}
where $\pi\mapsto \int_M B_{x,\mathrm{d} f(x)}(z)\pi(\mathrm{d}z)$ is bounded and continuous, and $\mathcal{I}(x,\cdot)$ has compact sub-level sets in $\mathcal{P}(S)$. Thus, there exists an optimizer $\pi_{\delta,m}\in\mathcal{P}(S)$ such that 
\begin{equation}\label{eqn_H1}
	\mathcal{H}(x_{\delta,m},p^1_{\delta,m})=\int_M B_{x_{\delta,m},p^1_{\delta,m}}(z)\pi_{\delta,m}(\text{d}z)-\mathcal{I}(x_{\delta,m},\pi_{\delta,m})
\end{equation}
and 
\begin{equation}\label{eqn_H2}
	\mathcal{H}(y_{\delta,m},p^2_{\delta,m})\leq \int_M B_{y_{\delta,m},p^2_{\delta,m}}(z)\pi_{\delta,m}(\text{d}z)-\mathcal{I}(y_{\delta,m},\pi_{\delta,m}).
\end{equation}
Combining \eqref{eqn_H1} and \eqref{eqn_H2}, we obtain 
\begin{align}
	\mathcal{H}&(x_{\delta,m},p^1_{\delta,m})-\mathcal{H}(y_{\delta,m},p^2_{\delta,m})\notag\\
	&\leq \int_M\big(B_{x_{\delta,m},p^1_{\delta,m}}(z)-B_{y_{\delta,m},p^2_{\delta,m}}(z)\big)\pi_{\delta,m}(\text{d}z)\label{eqn_B_B}\\
	&\quad+\mathcal{I}(y_{\delta,m},\pi_{\delta,m})-\mathcal{I}(x_{\delta,m},\pi_{\delta,m})\label{eqn_I-I}.
\end{align}
It is enough to prove that \eqref{eqn_B_B} and \eqref{eqn_I-I} are sufficiently small. For \eqref{eqn_B_B}, by calculating the difference of integrand  $B_{x,p}$ in detail, for any $z \in S$, from \eqref{eqn_BXI}, \eqref{eqn_P1} and \eqref{eqn_P2} one has
\begin{equation}\label{eqn:B-B}
\begin{split}
&B_{x_{\delta,m},p^1_{\delta,m}}(z)-B_{y_{\delta,m},p^2_{\delta,m}}(z)\\&
=m\mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m})b(x_{\delta,m},z)+\frac{1}{2}\left| m~ \mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m})  \right|^2\\
&-\left[ -m~\mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m})b(y_{\delta,m},z)+\frac{1}{2}\left| -m~\mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m})\right|^2 \right]\\
&=m\mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m})b(x_{\delta,m},z)+m~\mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m})b(y_{\delta,m},z) \\
&+\frac{m^2}{2}\left(\left|\mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m}) \right|^2-\left|- \mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m}) \right|^2\right)\\
&=m\mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m})b(x_{\delta,m},z)+m~\mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m})b(y_{\delta,m},z)\\
&
\leq Cd^2(x_{\delta,m},y_{\delta,m}),
\end{split}
\end{equation}
where in the last inequality, we use \Cref{ass_b_one_side}. Noting that
the last term in line 5 vanishes. This is happened because, fix $\delta>0$, there is a compact $K^\delta\subseteq M$ such that $\{x_{m,\delta},~y_{m,\delta}~|~m>0\}$ is contained in $K^\delta$ by \cref{item_iaa} of \Cref{lem_pro3.7}. By the continuity of the injectivity radius and the compactness of $K^\delta$, we can find a $\Delta>0$ such that $i(K^\delta)\geq \Delta >0$. Then there exists a unique geodesic of minimal length connecting $x_{m,\delta}$ and $y_{m,\delta}$. 
Furthermore, by \Cref{lem_dddd} we have
\begin{equation}\label{eqn_staud}
 \mathrm{d}_xd^2(\cdot,y_{m,\delta})(x_{m,\delta})=  -\tau_{x_{m,\delta},~y_{m,\delta}} \mathrm{d}_yd^2(x_{m,\delta},~\cdot)(y_{m,\delta}),
\end{equation}
where $\tau_{x_{m,\delta},y_{m,\delta}}$ denotes parallel transport along the unique geodesic of minimal length connecting $x_{m,\delta}$ and $y_{m,\delta}$. As parallel transport is an isometry, we find
\begin{equation*}
\left|\mathrm{d}_{x}\left(\frac{1}{2} d^2(\cdot,y_{\delta,m})\right)(x_{\delta,m}) \right|_{g(x)}^2=\left|- \mathrm{d}_y \left(\frac{1}{2}d^2(x_{\delta,m},\cdot)\right)(y_{\delta,m}) \right|^2_{g(y)}
\end{equation*}
\par
Hence, \eqref{eqn_B_B} is sufficiently small, as $m\to \infty$,  using \eqref{eq_md}  and \eqref{eqn:B-B}. 
We obtain that \eqref{eqn_I-I} is sufficiently small, utilize the equi-continuity of $\mathcal{I}(\cdot,\pi)$ established in \Cref{lem_Lip} below for the spatial variable. This finishes the proof of \eqref{eqn_H-H} and the comparison principle for $H_\dagger$ and $H_\ddagger$.

\label{lem_Lip}
Let \Cref{asm_conti_manifold} be satisfied. Recall \eqref{eqn_I(x,pi)}:
\begin{align*}
\mathcal{I}(x,\pi)&=-\inf_{g>0}\int_{M}\frac{R_{x}g(z)}{g(z)}\pi(\mathrm{d}z).
\end{align*}
For any compact set $K\subseteq M$ and for all $\pi\in \mathcal{P}(S)$, then $\{x\mapsto J(x,\pi)\}_{x\in K}$ is equi-continuous.

\label{pro_three_conditions}
	Suppose that $\mathcal{H}: T^*M\to \mathbb{R}$ is convex in $p$ and define $\mathcal{L}$ as its Lagrangian transform. Suppose that there is a good containment function $\Upsilon$ for $\mathcal{H}$. Then
	\begin{enumerate}
		\item \label{item_compact}the function $\mathcal{L}: TM\to [0,\infty]$ is lower semi-continuous and for each compact set $K\subseteq M$ and $c\in \mathbb{R}$ the set
		\begin{equation*}
			\{(x,v)\in TM ~|~x\in K,~ \mathcal{L}(x,v)\leq c\}
		\end{equation*}
		is compact in $TM$.
		\item \label{item_LleqC}for each compact $K\subseteq M$, any finite time $T>0$ and finite bound $C\geq 0$, there exists a compact set  $\hat{K}=\hat{K}(K,T,C)\subseteq M$ such that $x\in \mathcal{AC}(M)$ and $x(0)\in K$, if
		\begin{equation*}
			\int^T_0\mathcal{L}(x(s),\dot{x}(s))\mathrm{d}s\leq C,
		\end{equation*}
		then $x(t)\in \hat{K}$ for all $0\leq t\leq T$.
        \item \label{item:control_Psi_on_L_sets}

        for each compact set $K \subseteq M$ and $c \in \mathbb{R}$, there exists a right-continuous non-decreasing function $\psi_{K,c}:\mathbb{R}^+\to \mathbb{R}^+$ such that 
        \begin{equation}\label{eqn_Psi}
			\lim_{r\to \infty}r^{-1}\psi_{K,c}(r)=0.
		\end{equation}
        and
        \begin{equation*} \label{eqn:definition:}
			|\mathrm{d}f(x) {v}|\leq \psi_{K,c}(\mathcal{L}(x,v)), \qquad \forall \, (x,v) \in TM,~x \in K,
		\end{equation*}
        where $f \in C_{K,c}$ and
        \begin{equation}\label{eqn:def_C_Kc}
            C_{K,c} := \left\{f\in C^{\infty}_c(M) \, \middle| \, \forall \,x \in K,\,|df(x)|\leq c  \right\}.
        \end{equation}

	\end{enumerate}

	To obtain \Cref{item_compact}, observe that $\mathcal{L}\geq 0$ follows from $\mathcal{H}(x,0)=0$. The Lagrangian $\mathcal{L}$ is convex, and lower semicontinuous as it is the Legendre transform of $\mathcal{H}$, hence in particular continuous. For $C\geq 0$, we prove that the set $\{(x,v)\in TM :x\in K, \mathcal{L}(x,v)\leq C\}$ is bounded, and hence is relatively
	compact. For any $p \in T^*_xM$ and $v\in T_xM$, we have 
	\begin{equation*}
		p v \leq \mathcal{L}(x,v) + \mathcal{H}(x,p)~~x\in K. 
	\end{equation*} Thereby, if
	$\mathcal{L}(x,v) \leq C$, then \begin{equation*}
		|v| = \sup \limits_{|p|=1}
		p  v \leq  \sup\limits_{|p|=1}
		[\mathcal{L}(x,v) + \mathcal{H}(x,p)] \leq C + C_1,    
	\end{equation*} where
	$C_1$ exists due to continuity of $\mathcal{H}$ and $x\in K$. Then for $R := C + C_1$,
	\begin{equation*}
		\{(x,v)\in TM: \mathcal{L}(x,v)\leq C\} \subseteq \{v :
		|v| \leq R\},
	\end{equation*}
	thus $\{\mathcal{L} \leq C\}$ is a bounded subset in $TM$.
	\par
	For \cref{item_LleqC}, recalling that the level sets of $\Upsilon$ are compact, we control the growth of $\Upsilon$. For $K\subseteq M$, $T>0$, $C\geq 0$ and $x\in \mathcal{AC}(M)$ as above, this follows by noting that 
	\begin{align*} \Upsilon(x(t))&=\Upsilon(x(0))+\int^t_0\mathrm{d} \Upsilon(x(s))\dot{x}(s)\mathrm{d}s\\
		&\leq\Upsilon(x(0))+\int^t_0\left[\mathcal{L}(x(s),\dot{x}(s))+\mathcal{H}(x(s),\mathrm{d} \Upsilon(x(s)))\right]\mathrm{d}s\\
		&\leq \sup_{y\in K}\Upsilon(y)+C_1+T\sup_{z\in M}\mathcal{H}(z,\mathrm{d}\Upsilon(z))=C<\infty,
	\end{align*}
	for any $0\leq t \leq T$, so that the compact set $\hat{K}=\{z\in M:\Upsilon(x)\leq C\}$ satisfies the condition.
	\par
 Proof of \ref{item:control_Psi_on_L_sets} is inspired by that of Lemma 10.21 of \cite{FK2006}. We first prove that $\mathcal{L}(x,v)$ is superlinear. Recall that $\mathcal{H}$ is continuous, which implies
    \begin{equation*}
        \overline{H}_K(c) := \sup_{x \in K} \, \, \sup_{p \in T_x^*M, |p| \leq c} \mathcal{H}(x,p) < \infty.
    \end{equation*}
    Using the definition of $\mathcal{L}$, it thus follows for any $(x,v) \in TM$, $x \in K$ with $|v| > 0$ that
    \begin{equation*}
        \frac{\mathcal{L}(x,v)}{|v|} \geq \sup_{p \in T_x^*M, \, |p| \leq c} \frac{pv}{|v|} - \frac{\overline{H}_K(c)}{|v|} = c - \frac{\overline{H}_K(c)}{|v|}
    \end{equation*}
    It follows that
    \begin{equation*}
        \lim_{N \uparrow \infty} \, \,   \inf_{x \in K} \, \,  \inf_{v \in T_xM: |v| = N} \frac{\mathcal{L}(x,v)}{|v|} = \infty.
    \end{equation*}

	Secondly, for $s\geq 0$, define the map $\vartheta(s)$ by
	\begin{equation}\label{eqn_Lv}
		\vartheta(s):= s \inf_{x \in K} \inf_{v \in T_xM: |v| \geq s}\frac{\mathcal{L}(x,v)}{|v|}.
	\end{equation}
	It thus follows that $\vartheta$ is a strictly increasing function satisfying
    \begin{equation}\label{eqn:divergence_vartheta}
        \lim_{s \uparrow \infty} \frac{\vartheta(s)}{s} = \infty.
    \end{equation}
 Next, define $\Psi_{K,c}(r):C_{K,c}\vartheta^{-1}(r)$ with $\vartheta^{-1}(r)=\inf\{\omega:\vartheta(\omega)\geq r\}$. By monotonicity of $\vartheta$, we have for any $x \in K$ that
	\begin{equation*}
		\vartheta(C^{-1}_{K,c}|\mathrm{d}f(x) v|)\overset{\eqref{eqn:def_C_Kc}}\leq \vartheta(|v|) \overset{\eqref{eqn_Lv}}\leq \mathcal{L}(x,v).
	\end{equation*}
	Hence by monotonicity of $\Psi_{K,c}$, we find $|\mathrm{d} f(x) v|\leq \Psi_{K,c}(\mathcal{L}(x,v))$ for any $f \in C_{K,c}$, and $(x,v) \in TM$ with $x \in K$. Finally \eqref{eqn_Psi} follows by \eqref{eqn:divergence_vartheta} and the definition of $\vartheta^{-1}(r)$.

\Cref{pro_three_conditions} can be used to obtain the path-space compactness of the set of trajectories that start in a compact set and have uniformly bounded Lagrangian cost. The compactness of this set can be used to get the two properties of $\mathbf{V}$ and $\mathbf{R}$.
\begin{itemize}
	\item the resolvents approximate the semigroups as in the Crandall–Ligget theorem, see \cite[Lemma 8.18]{FK2006},
	\begin{equation*}
		\lim_{n\to \infty} \mathbf{R}(t/n)^{n}f(x) = \mathbf{V}(t) f(x); 
	\end{equation*}
	\item the resolvent $\mathbf{R}(\lambda)h$ is a viscosity subsolution to the Hamilton-Jacobi-Bellman equations $f-\lambda \mathbf{H}f=h$, $\lambda> 0$ and $h \in C_b(M)$.
\end{itemize}

 \label{lemma:control_on_local_curves_compactness} Under \Cref{ass_bfH_bounded},
let $K_0\subseteq M$ a compact set and $T > 0$. For any $f\in \mathcal{D}(\mathbf{H})$, then there is a compact set $\hat{K} \subseteq M$ such that any curve $x : [0,T_0)\to M$ with $T_0 \leq T$ satisfying $x(0) \in K_0$ and for all $t < T_0$
\begin{equation} \label{eqn:satisfy_Young}
    \int_0^t \mathbf{H}f(x(s)) \mathrm{d} s + \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s = \int_0^t \mathrm{d} f(x(s)) \dot{x}(s) \mathrm{d} s
\end{equation}
it holds that $x(t) \in \hat{K}$ for any $t < T_0$.

    Write $c_f := \sup_{z} \left\{ -\mathbf{H}f(z) \right\}$ and $\|f\|=\sup_x|f(x)|$. Note that by \eqref{eqn:satisfy_Young}, we have for any curve
\begin{equation*}
