\end{equation*}
the result thus follows by Proposition \ref{pro_three_conditions} \ref{item_LleqC}.

\begin{equation*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s = f(x(t)) - f(x(0)) - \int_0^t \mathbf{H}f(x(s)) \mathrm{d} s  \leq 2 \vn{f} + tc_f \leq 2 \vn{f} + T c_f
