\label{pro_pro_three_conditions_super}
Under \Cref{ass_bfH_bounded},
for initial point $x(0)\in M$ and any $f\in \mathcal{D}(\mathbf{H})$, there exists an absolutely continuous curve $x:[0,\infty)\to M$ and for all $0<t\leq T$ such that
	\begin{equation}\label{eqn_global_local}
		\int^t_0\mathcal{H}(x(s),\mathrm{d} f(x(s)))\mathrm{d}s+\int^t_0\mathcal{L}(x(s),\dot{x}(s))\mathrm{d}s=\int^t_0\mathrm{d}f(x(s))\dot{x}(s)\mathrm{d}s.
	\end{equation}

\label{lem_lemma1}
	Let $\mathcal{O}\subset M$ be a Riemannian manifold. For an invertible smooth map $\varphi: \mathcal{O}\to \varphi(\mathcal{O}):=N$, via push-forward and pullback  in \Cref{se_Riemannian_manifold} define 
	\begin{equation*} \mathcal{H}_{\varphi}:=\mathcal{H}\circ \varphi^*:T^*N \to \mathbb{R}
	\end{equation*}
	and 
	\begin{equation*}
		\mathcal{L}_\varphi:=\mathcal{L}\circ \varphi^{-1}_*:TN\to \mathbb{R},
	\end{equation*} 
	where $\mathcal{H}:T^*M\to \mathbb{R}$ and $\mathcal{L}:TM\to \mathbb{R}$. Suppose $x : [0,\infty) \rightarrow \mathcal{O}$ is any curve such that $y(s)=\varphi(x(s))$, 
	then we have that
	\begin{enumerate}[(a)]
		\item \label{item_HL2}  
		$\mathrm{d}(f\circ\varphi^{-1})(y(s))\dot{y}(s)=\mathrm{d}f(x(s))\dot{x}(s)$,
		\item \label{item_HL3} $
		\mathcal{H}_{\varphi}(y(s),\mathrm{d} (f \circ \varphi^{-1})(y(s)))=\mathcal{H}(x(s),\mathrm{d}f(x(s)))
		$,
		\item \label{item_HL4} 
		$
		\mathcal{L}_{\varphi}(y(s),\dot{y}(s))=\mathcal{L}(x(s),\dot{x}(s))$.
		\item \label{item_HL1} $\mathcal{L}_\varphi $ is the Legendre transform of $\mathcal{H}_\varphi$, i.e.,
		$\mathcal{H}_\varphi(\eta,\xi)=\sup_{w\in T_{\eta}N}\left\{\xi(w)-\mathcal{L}_\varphi(\eta,w)\right\}$, for any $(\eta,\xi)\in T^*N$.
	\end{enumerate}

We start to prove
\cref{item_HL2}. By \Cref{lem_acurve}, 
there exists a curve $x(s)$ on $\mathcal{O}$ such that
\begin{align*}
	\mathrm{d}(f\circ\varphi^{-1})(y(s))\dot{y}(s)&=\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s)))\varphi_{*}(\dot{x}(s))\\
	&=\mathrm{d}f(x(s))\dot{x}(s),
\end{align*}
where in the last show we used the fact that
\begin{equation}\label{eqn_there_a_curve}
	\begin{split}
		\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s)))&=\mathrm{d}f(\varphi^{-1}(\varphi(x(s))))\mathrm{d}(\varphi^{-1}(\varphi(x(s))))\phi_{*}(\dot{x}(s))\\
		&=\mathrm{d}f(x(s))\frac{\mathrm{d}}{\mathrm{d}t}\bigg|_{t=s}\varphi^{-1}
		(\varphi(x(t)))\\

		&=\mathrm{d}f(x(s))\dot{x}(s).
	\end{split}
\end{equation}
\par
We prove \cref{item_HL3} based on the ideas when we obtain \cref{item_HL2}.
Since
\begin{align*}
	\mathcal{H}_{\varphi}(y(s),\mathrm{d} (f\circ \varphi^{-1})(y(s)))&=\mathcal{H}\circ \varphi^*(\varphi(x(s)),\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s)))\\
	&=\mathcal{H}(x(s),\varphi^*(\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s))),
\end{align*}
it suffices to prove
\begin{align}\label{eqn_QPG}
	\varphi^*(\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s))=\mathrm{d}f(x(s)).
\end{align}
Indeed, applying the chain rule \eqref{eqn_chain_rule}, we imply 
\begin{align*}
	\varphi^*(\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s))
	&=\mathrm{d}(f\circ \varphi^{-1})(\varphi(x(s))(\varphi_{*}(x(s)))\\
	&=\mathrm{d}f(\varphi^{-1}(\varphi(x(s))))\mathrm{d}(\varphi^{-1}(\varphi(x(s))))(\varphi_{*}(x(s))))\\
	&
	=\mathrm{d}f(x(s)),
\end{align*}
where in the last equality we use \eqref{eqn_there_a_curve}.
Therefore, \eqref{eqn_QPG} holds. We continue to prove \cref{item_HL4} by simple calculating, and get 
\begin{align*}
	\mathcal{L}_{\varphi}(y(s),\dot{y}(s))&=\mathcal{L}\circ \varphi^{-1}_{*}(\varphi(x(s)),\varphi_{*}(\dot{x}(s)))\\
	&=\mathcal{L}(x(s),\dot{x}(s)).
\end{align*}
To prove \cref{item_HL1}, for any $(\eta,\xi)\in T^*N$, we have
\begin{align*}
	\mathcal{H}_\varphi(\eta,\xi)&=\mathcal{H}(\varphi^{-1}(\eta),\varphi^*(\xi))\\
	&=\sup_{v\in T_\eta M}\left\{\varphi^*(\xi)(v)-\mathcal{L}(\varphi^{-1}(\eta),v)\right\}\\
	&\overset{\eqref{eqn_xiX}}{=}\sup_{\varphi_*(v)\in T_{\eta}N}\left\{\xi(\varphi_*(v))-\mathcal{L}_\varphi(\eta ,\varphi_*(v))\right\}\\
	&=\sup_{w\in T_{\eta}N}\left\{\xi(w)-\mathcal{L}_\varphi(\eta,w)\right\},
\end{align*}
where the second equality is the fact that $\mathcal{L}$ is the Legendre transform of $\mathcal{H}$. 
The proof is completed.

For a general convex functional $p \mapsto \Phi(p)$ we denote the subdifferential at $p_0\in \mathbb{R}^d$ as the set
\begin{equation*}
	\partial_p\Phi(p_0):=\{\xi \in \mathbb{R}^d:\Phi(p)\geq \Phi(p_0)+\xi(p-p_0),\forall p\in \mathbb{R}^d\}.
\end{equation*}

\label{lemma:local_existence}
Let $M$ be a Riemannian manifold and let $x_0 \in M$. Consider the open ball $\mathcal{O} := B_{R}(x_0)$ around $x_0$ with the radius $R > 0$ strictly smaller than the injectivity radius $i_{x_0}$ at $x_0$. Denote the normal coordinates on the ball $\mathcal{O}$ by the map $\varphi : \mathcal{O} \subseteq M \rightarrow \varphi(\mathcal{O}) \subseteq \mathbb{R}^d$.

    Fix $f \in C^1(M)$. Then the following content holds.
    \begin{enumerate}
        \item \label{item:local_existence_on_chart} Define $f_\varphi=f\circ\varphi^{-1}$. There exists a solution $y(t) : [0,T_0(x)) \rightarrow \varphi(\mathcal{O}) \subseteq \mathbb{R}^d$ to the differential inclusion
    \begin{equation}\label{eqn_y_differ_inclu}
    \begin{cases}
        \dot{y}(t)\in \partial_p\mathcal{H}_\varphi(y(t),\mathrm{d}f_{\varphi}(y(t)), \\
        y(0) = 0 = \varphi(x_0)
    \end{cases}
	\end{equation}
    with 
    \begin{equation}
        T_0(x) = \inf \left\{ t > 0 \, \middle| \, y(t) \notin \varphi(B_{R/2}(x_0)) \right\}.
    \end{equation}
    \item \label{item:local_existence_integral_equality} Set $x(t) = \varphi^{-1}(y(t))$. Then the curve $x : [0,T_0(x)) \rightarrow B_{R/2}(x_0) \subseteq M$ satisfies $x(0) = x_0$ and
    \begin{equation}\label{eqn_T0V}
	\int^{t}_0\mathcal{H}(x(s),\mathrm{d} f(x(s)))\mathrm{d}s+\int^{t}_0\mathcal{L}(x(s),\dot{x}(s))\mathrm{d}s=\int^{t}_0\mathrm{d}f(x(s))\dot{x}(s)\mathrm{d}s.
	\end{equation}
    for any $t < T_0(x)$.
    \end{enumerate}

	We first prove the differential inclusion \eqref{eqn_y_differ_inclu}. By taking $\mathcal{O}=B_{R}(x_0)$ in \Cref{lem_lemma1} and define $T_0(x) = \inf \left\{ t > 0 \, \middle| \, y(t) \notin \varphi(B_{R/2}(x_0)) \right\}$, we transfer a differential inclusion on $M$ to the chart $\varphi(\mathcal{O})\subseteq \mathbb{R}^d$, and obtain \eqref{eqn_y_differ_inclu}. The subdifferential $\partial_p\mathcal{H}_\varphi(y(t),\mathrm{d}f_\varphi(y(t))$ satisfies all the conditions of Lemma 5.1 of \cite{D1992MR1189795}. Hence, there exists a solution $y(t)$ such that \eqref{eqn_y_differ_inclu} holds.
	\par
	Next, we turn to prove that there exists a solution such that \eqref{eqn_T0V} holds by local construction. To do it, for the initial point $x_0\in M$, there exists a ball $B_{R}(x_0)$ with $R$ strictly smaller than   $i_{x_0}$. By \eqref{eqn_y_differ_inclu}, we further have
\begin{equation}\label{eqn_Uy}
\int^t_0\mathcal{H}_{\varphi}(y(s),\mathrm{d} f_{\varphi}(y(s)))\mathrm{d}s+\int^t_0\mathcal{L}_{\varphi}(y(s),\dot{y}(s))\mathrm{d}s=\int^t_0\mathrm{d}f_{\varphi}(y(s))\dot{y}(s)\mathrm{d}s.
	\end{equation}
 on $\varphi(\mathcal{O})$.
 \par
 We claim that there exists a curve $y(s):[0,T_0(x))\to \varphi(\mathcal{O})$ such that \eqref{eqn_Uy} holds. 
  On the one hand, we have that
		\begin{equation*}
			\mathcal{H}_\varphi(y(s),\mathrm{d}f_{\varphi}(y(s) ))\geq \mathrm{d}f_{\varphi}(y(s))\dot{y}(s)-\mathcal{L}_\varphi(y(s),\dot{y}(s)),
	\end{equation*}
	for all $y(s)\in \varphi(\mathcal{O})$, via convex duality.
Then, integrating the above inequality gives one inequality in \eqref{eqn_Uy}.
\par Regarding the other inequality, via \eqref{eqn_y_differ_inclu} we obtain for all $p\in \varphi(\mathcal{O})$, 
\begin{equation*}
	\mathcal{H}_\varphi (y(s),p)\geq \mathcal{H}_\varphi(y(s),\mathrm{d}f_{\varphi}(y(s) ))+ \dot{y}(s) \left(p- \mathrm{d}f_{\varphi}(y(s))\right),
\end{equation*}
and as a consequence
\begin{align*}
\mathcal{H}_\varphi(y(s),\mathrm{d}f_{\varphi}(y(s) ))\leq \mathrm{d}f_{\varphi}(y(s))\dot{y}(s)-\mathcal{L}_\varphi(y(s),\dot{y}(s)),
\end{align*}
and integrating gives the other inequality.
After that by \Cref{lem_lemma1}, we transfer \eqref{eqn_Uy} on $\phi(\mathcal{O})$ to \eqref{eqn_T0V} on $M$. Then we get a curve $x(t)=\varphi^{-1}(y(s))\subseteq \mathcal{O}\subseteq M$ satisfying \eqref{eqn_T0V} for any $s < T_0(x)$.

 \label{lemma:local_existence_control_on_Lagrangian}

Let $M$ be a Riemannian manifold and $K\subseteq M$ a compact set. Fix $R \in [i(K)/2,i(K))$. Then there is a constant $C$ such that for any curve $x(t) : [0,T_0(x)) \rightarrow B_{R/2}(x_0)$ with $x(0) \in K$ as in Lemma \ref{lemma:local_existence}, we have
    \begin{equation*}
        \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s \leq C t
    \end{equation*}
    for any $t < T_0(x)$.

First of all, denote by $\hat{K}$ the compact set obtained by covering $K$ by balls of radius $R/2$. No considered curve can leave $\hat{K}$ by construction.

Denote $c_{f,\hat{K}}=\sup_{z\in\hat{K}}\{-\mathbf{H}f(z)\}$. 
As $x$ satisfies \eqref{eqn_T0V}, we have by Proposition \ref{pro_three_conditions}  \ref{item:control_Psi_on_L_sets}
\begin{align*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s & = \int_0^t \mathrm{d} f(x(s)) \dot{x}(s) \mathrm{d} s - \int_0^t \mathbf{H}f(x(s)) \mathrm{d} s \\
    & \leq \int_0^t \psi_{\hat{K},R} \left(\mathcal{L}(x(s),\dot{x}(s)) \right)\mathrm{d} s+ t c_{f,\hat{K}}.
\end{align*}
Furthermore, as $\psi_{\hat{K},R}$ is non-decreasing and the fact that $\frac{\psi_{\hat{K},R}(r)}{r}$ converges to $0$ for $r\to \infty$, there exist $0<m<1$ and $r^*\geq 1$ such that $\frac{\Psi_{\hat{K},R}(r)}{r}\leq m$ for $r \geq r^*$. Proceeding our estimate, by splitting the integral into regions $[0,t] = I_1 \cup I_2$ with
\begin{align*}
    I_1 & := \left\{s \in [0,t] \, \middle| \, \mathcal{L}(x(s),\dot{x}(s)) \geq r^*\right\}, \\
    I_2 & := \left\{s \in [0,t] \, \middle| \, \mathcal{L}(x(s),\dot{x}(s)) < r^*\right\},
\end{align*}
we get
\begin{align*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s  & \leq \int_{I_1} \frac{\psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s)))}{\mathcal{L}(x(s),\dot{x}(s))}\mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s +\int_{I_2} \psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s))) \mathrm{d} s + tc_{f,\hat{K}}\\
    & \leq m \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s + t \left( \psi_{\hat{K},R}(r^*) + c_{f,\hat{K}}\right).
\end{align*}
Rearranging terms leads to
\begin{equation*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s \leq t \frac{\psi_{\hat{K},R}(r^*) + c_{f,\hat{K}}}{1-m}
\end{equation*}
establishing the claim with $C=\frac{\psi_{\hat{K},R}(r^*) + c_{f,\hat{K}}}{1-m}$.

\begin{align*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s & = \int_0^t \mathrm{d} f(x(s)) \dot{x}(s) \mathrm{d} s - \int_0^t \mathbf{H}f(x(s)) \mathrm{d} s \\
    & \leq \int_0^t \psi_{\hat{K},R} \left(\mathcal{L}(x(s),\dot{x}(s)) \right)\mathrm{d} s+ t c_{f,\hat{K}}.
\end{align*}

\begin{align*}
    \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s  & \leq \int_{I_1} \frac{\psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s)))}{\mathcal{L}(x(s),\dot{x}(s))}\mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s +\int_{I_2} \psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s))) \mathrm{d} s + tc_{f,\hat{K}}\\
    & \leq m \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s + t \left( \psi_{\hat{K},R}(r^*) + c_{f,\hat{K}}\right).
\end{align*}

 \label{lemma:control_on_local_curves}
Let $M$ be a Riemannian manifold and $K\subseteq M$ a compact set. Fix $R \in [i(K)/2,i(K))$. 

Then there is a $C > 0$ such that for any $x_0 \in K$ and any curve $x(t) : [0,T_0(x)) \rightarrow B_{R/2}(x_0)$ with $x(0) = x_0$ as in Lemma \ref{lemma:local_existence}, we have
\begin{equation*}
    \frac{1}{2}d^2(x(t),x_0) \leq t C
\end{equation*}
for any $t < T_0(x)$. In particular $T_0(x) \geq \frac{R^2}{8C}$.

 \label{lemma:smooth_distance_cutoff}
Let $K \subseteq M$ be a compact set in $M$. For any $x_0 \in K$ and radius $R < i_{x_0}$, set
\begin{equation*}
    g_{x_0,R}(x) = \theta_R\left(\frac{1}{2}d^2(x,x_0)\right)
\end{equation*}
where $\theta_R : [0,\infty) \rightarrow [0,\frac{3}{4}R]$ is a smooth non-decreasing function, satisfying $\theta'_R(r) \leq 1$ where $\theta_R(r) = r$ for $r \leq R/2$ and $\theta_R(r)$ is constant for $r \geq \frac{3}{4}R$.

For any such $R$, we have $g_{x_0,R} \in C_{K,R}$ where $C_{K,R}$ was defined in Proposition \ref{pro_three_conditions} \ref{item:control_Psi_on_L_sets}. Moreover, $g_{x_0,R}\in \mathcal{D}(\mathbf{H})$.

    By construction, we have
    \begin{equation*}
        \mathrm{d} g_{x_0,R}(x) = \theta_R'\left(\frac{1}{2}d^2(x,x_0)\right) d(x,x_0)
    \end{equation*}
    which by the properties of $\theta_R$ satisfies
    \begin{equation*}
        | \mathrm{d} g_{x_0,R}(x) | \leq |d(x,x_0)| \leq R
    \end{equation*}
    for any $x \in M$. In particular, we have $g_{x_0,R} \in C_{K,M}$.
    \par
    We proceed to prove $g_{x_0,R}\in \mathcal{D}(\mathbf{H})$. To do it, since  $g_{x_0,R}$ is continuously differentiable and bounded, we are left to prove that there exists a $C>0$ such that $\sup_{z}\left\{-\mathbf{H}g_{x_0,R}(z)\right\}\leq C$.
    On the one hand, we have
    \begin{equation}\label{eqn:g1}
    \begin{split}
        \int^t_0\mathrm{d} g_{x_0,R}(x(s))\dot{x}(s)\mathrm{d} s=g_{x_0,R}(x(t))-g_{x_0,R}(x(0))=\frac{1}{2}d^2(x(t),x_0)\geq 0.
    \end{split}
    \end{equation}
    On the other hand, we have
\begin{equation}\label{eqn:g2}
        \int^t_0\mathrm{d} g_{x_0,R}(x(x))\dot{x}(s)\mathrm{d} s=\int^t_0\mathcal{L}(x(s),\dot{x}(s))\mathrm{d} s+\int^t_0\mathbf{H}g_{x_0,R}(x(s))\mathrm{d} s. 
    \end{equation}
    Form \eqref{eqn:g1} and \eqref{eqn:g2}, we obtain that
\begin{equation}\label{eqn:g3}
    \begin{split}
        -\int^t_0\mathbf{H}g_{x_0,R}(x(s))\mathrm{d} s &\leq\int^t_0\mathcal{L}(x(s),\dot{x}(s))\mathrm{d} s\leq Ct,
    \end{split}
    \end{equation}
 where in the last inequality we use  \Cref{lemma:local_existence_control_on_Lagrangian} for the above estimate. Furthermore, form \eqref{eqn:g3}  we obtain $\sup_{z}\left\{-\mathbf{H}g_{x_0,R}(z)\right\}\leq C$ which deduce that $g_{x_0,R}\in \mathcal{D}(\mathbf{H})$.

Fix $x_0 \in K$ and any curve $x(t) : [0,T_0(x)) \rightarrow B_{R/2}(x_0)$ with $x(0) = x_0$ as in Lemma \ref{lemma:local_existence}. Let $g_{x_0,R} \in \mathcal{D}(\mathbf{H})$ be any smooth bounded function as in Lemma \ref{lemma:smooth_distance_cutoff} and $\hat{K}$ be the compact set obtained by covering $K$ by balls of radius $R/2$. 
For the sake of symbol simplicity, we will write $g_{x_0,R}$ as $g$.
\par
It thus follows by Proposition \ref{pro_three_conditions} \ref{item:control_Psi_on_L_sets} and \eqref{eqn:g1} that for any $t < T_0(x)$
\begin{align*}
    \frac{1}{2}d^2(x(t),x_0) 
    & = \int_0^t \mathrm{d} g(x(s)) \dot{x}(s) \mathrm{d} s \\
    & \leq \int_0^t \psi_{\hat{K},R}\left( \mathcal{L}(x(s),\dot{x}(s))\right) \mathrm{d} s.
\end{align*}
As $\psi_{\hat{K},R}$ is non decreasing and the fact that $\frac{\psi_{\hat{K},R}(r)}{r}$ converges to $0$ for $r\to \infty$, there exist $0<m<1$ and $r^*\geq 1$ such that $\frac{\Psi_{\hat{K},R}(r)}{r}\leq m$ for $r \geq r^*$. Proceeding our estimate, by splitting the integral into regions $[0,t] = I_1 \cup I_2$ with
\begin{align*}
    I_1 & := \left\{s \in [0,t] \, \middle| \, \mathcal{L}(x(s),\dot{x}(s)) \geq r^*\right\}, \\
    I_2 & := \left\{s \in [0,t] \, \middle| \, \mathcal{L}(x(s),\dot{x}(s)) < r^*\right\},
\end{align*}
we get
\begin{align*}
    \frac{1}{2}d^2(x(t),x_0) & \leq \int_{I_1} \frac{\psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s)))}{\mathcal{L}(x(s),\dot{x}(s))}\mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s +\int_{I_2} \psi_{\hat{K},R}(\mathcal{L}(x(s),\dot{x}(s))) \mathrm{d} s \\
    & \leq m \int_0^t \mathcal{L}(x(s),\dot{x}(s)) \mathrm{d} s + t \psi_{\hat{K},R}(r^*).
\end{align*}
By \Cref{lemma:local_existence_control_on_Lagrangian}, we conclude that
\begin{equation*}
    \frac{1}{2}d^2(x(t),x_0)  \leq t\left(mC_1+ \psi_{\hat{K},R}(r^*)\right).
\end{equation*}
The result thus follows for $C = mC_1 + \psi_{\hat{K},R}(r^*)$.

