 The large deviation principle with an action-integral rate function can be obtained from
\Cref{pro_convergence_of_operator,lem_eigen,pro_expo,pro_compa_prin} and \Cref{thm_viscosity_solution}. 
 Based on the proof of \cite[Theorem 8.14]{FK2006} that if semigroups $V(t)$ and $\mathbf{V}(t)$ agree, then the rate function 
  \begin{equation*}
	I(\gamma)=
	\begin{cases}
		I_0(\gamma(0))+\int^\infty_0\mathcal{L}\left(\gamma(s),\dot{\gamma}(s)\right)\mathrm{d}s,&\mbox{if~$\gamma\in\mathcal{AC}(M)$,}\\
		\infty,&\mbox{otherwise.}
	\end{cases}
\end{equation*}
  Then the proof is completed.

Let $x\in M$. For any $X\in \mathbb{S}_x:=\{X\in T_xM:~|X|=1\}$, let
\begin{equation*}
	r(X):=\sup\{t>0:d(x,~\exp_x(tX))=t\}.
\end{equation*}
If $r(X)<\infty$ then we call $\exp_x(r(X)X)$ a cut-point of $x$. The set
\begin{equation*}
	\mathrm{cut}(x):=\{\exp_x(r(X)X)~:~X\in \mathbb{S}_x,~r(X)<\infty\}
\end{equation*}
is called the \textit{cut-locus} of the point of $x$. Moreover, the quantity
\begin{equation*}
	i_x:=\inf\{r(X):X\in \mathbb{S}_x\}
\end{equation*}
is called the \textit{injectivity radius} of $x$. For any set $A \subseteq M$ we write $i(A) := \inf_{x\in A} i_x $ the injectivity radius of $A$.

Let $\mathcal{T}(M)$ be the space of smooth vector ﬁelds on $M$ and let $\nabla$ be any connection on $M$. The formula
\begin{equation*}
	\mathcal{R}(X,Y)Z:=\nabla_Y\nabla_XZ-\nabla_X\nabla_YZ+\nabla_{[X,Y]}Z,
\end{equation*}
for $X$, $Y$, $Z\in \mathcal{T}(M)$, defines a function
$\mathcal{R}:\mathcal{T}(M)\times \mathcal{T}(M)\times \mathcal{T}(M)$ called the Riemannian curvature of $M$, where $[X,Y]=XY-YX$ is the commutator of $X$ and $Y$.

If $M$ and $N$ are smooth manifolds and $\varphi:M\to N$ is a smooth map, for each $p\in M$ we define a map 
\begin{equation}\label{eqn_push_forward}
	\varphi_{*p}:T_pM\to T_{\varphi(p)}N,
\end{equation} called the \textit{push-forward} associated with $\varphi$, by
\begin{equation*}
	(\varphi_{*p}(v))(f)=v(f\circ \varphi),~~~v\in T_pM,~f\in C^\infty(M).
\end{equation*}

Let 
$\varphi: M\to N$ be an invertible smooth map, and let $p\in M$ be arbitrary. 
A dual map by pullback associated with $\varphi$,
\begin{equation*}
	\varphi^*_p:T^*_{\varphi(p)} N \to T^*_pM.
\end{equation*}
Moreover, $\varphi^{*}_p$ is characterized by
\begin{equation}\label{eqn_xiX}
	(\varphi^{*}_p\xi)(v)=\xi(\varphi_{*p}(v)), ~~\mbox{for}~\xi \in T^*_{\varphi(p)} N,~v\in T_pM.
\end{equation}
We can put all $\varphi_{*p} $ and $\varphi^*_p$ together to obtain $\varphi_*:TM\to TN$ and $\varphi^*:T^*N \to T^*M$, respectively.

\label{lem_acurve}
	Let $\varphi:M\to N$ be a smooth map, and let $\gamma:J \to M$ be a smooth curve, where $J\in \mathbb{R}$ is an interval. For any $t\in J$, the tangent vector to the composite curve $\varphi \circ \gamma$ at $t = t_0$ is given by
	\begin{equation*}
		(\dot{\varphi\circ \gamma})(t_0)=(\varphi\circ \gamma)_*\frac{\mathrm{d}}{\mathrm{d}t}\bigg|_{t_0}=\varphi_*\dot{\gamma}(t_0).
	\end{equation*}

Suppose $V$, $W$, $X$ are finite-dimensional vector spaces, $U\subset V$ and $\Tilde{U}\subset W$ are open sets, and $F:U \to\Tilde{U}$ and $G:\Tilde{U}\to X$ are maps. If $F$ is differentiable at $a \in U$ and $G$ is diifferentiable at $F(a)\in U$, then $G\circ F$ is differentiable at $a$, and
\begin{equation}\label{eqn_chain_rule}
	D(G \circ F)(a) = DG(F(a)) \circ DF(a). 
\end{equation}

 \label{def_VS}Let $H\subseteq C_b(M)\times C_b(M\times S)$ be a multivalued operator. We denote $\mathcal{D}(H)$ for the domain of $H$ and $\mathcal{R}(H)$ for the range of $H$. Let $\lambda>0$ and $h\in C_b(M)$. Consider the Hamilton-Jacobi equations
	\begin{equation}\label{HJ}
		f-\lambda H f=h.
	\end{equation}
	\begin{description}
		\item [Classical solutions] 
		We say that $u$ is a classical subsolution of \eqref{HJ} if there is a $g$ such that $(u,g)\in H$ and $u - \lambda g \leq h$. We say that $v$ is a classical supersolution of \eqref{HJ} if there is a function $g$ such that $(v, g) \in H$ and $v - \lambda g \geq h$. We say that $u$ is a classical solution if it is both a subsolution and a supersolution.
		\item[Viscosity subsolutions] We say that $u$ is a (viscosity) subsolution of \eqref{HJ} if $u$ is bounded, upper semicontinuous, and if for every $(f,g)\in H$ there exists a sequence $(x_n,z_n) \in M\times S$ such that
		\begin{equation*}
			\lim_{n\to\infty}u(x_n)-f(x_n)=\sup_{x}u(x)-f(x),
		\end{equation*}
		\begin{equation*}
			\limsup_{n\to\infty}u(x_n)-\lambda g(x_n,z_n)-h(x_n)\leq 0.
		\end{equation*}
		\item[Viscosity supersolutions] We say that $v$ is a (viscosity) supersolution of \eqref{HJ} 
		if $v$ is bounded, lower semicontinuous, and if for every $(f,g)\in H$ there exists a sequence sequence $(x_n,z_n) \in M\times S$ such that
		\begin{equation*}
			\lim_{n\to\infty}v(x_n)-f(x_n)=\inf_{x}v(x)-f(x),
		\end{equation*}
		\begin{equation*}
			\liminf_{n\to\infty}v(x_n)-\lambda g(x_n,z_n)-h(x_n)\geq 0.
		\end{equation*}
		\item [Viscosity solutions] We say that $u$ is a (viscosity) solution of \eqref{HJ} if it is both a subsolution and a supersolution to \eqref{HJ}. 
	\end{description}

Consider the definition of subsolutions. Suppose that the test function $(f,g)\in H$ has compact sublevel sets, then instead of working with a sequence $(x_n,z_n)$, we can pick $(x_0,z_0)$ such that
\begin{equation*}
	u(x_0)-f(x_0)=\sup_{x}u(x)-f(x),
\end{equation*}
\begin{equation*}
	u(x_0)-\lambda g(x_0,z_0)-h(x_0)\leq 0.
\end{equation*}
Similarly, a simplification holds in the case of supersolutions. This is used in the proof \Cref{lem_1d} below.
